from scripts import resync_iscam_pagos_unidad as mod


def test_retry_recovers_transient_daily_error(monkeypatch):
    calls = []
    responses = [
        {"error": "OperationalError: transient"},
        {"unidad": "ORIGEN", "pagos_extraidos": 7, "pagos_insertados": 7},
    ]

    def fake_resync(unidad, fi, ff, dry_run=False):
        calls.append((unidad, fi, ff, dry_run))
        return responses.pop(0)

    monkeypatch.setattr(mod, "resync_pagos_unidad", fake_resync)
    result, attempts = mod._resync_window_with_retry(
        "ORIGEN", "2026-08-01", "2026-08-02", True, sleep_fn=lambda _: None
    )
    assert attempts == 2
    assert not result.get("error")
    assert len(calls) == 2


def test_retry_stops_after_four_failures(monkeypatch):
    calls = []

    def fake_resync(unidad, fi, ff, dry_run=False):
        calls.append(1)
        return {"error": "OperationalError: persistent"}

    monkeypatch.setattr(mod, "resync_pagos_unidad", fake_resync)
    result, attempts = mod._resync_window_with_retry(
        "ORIGEN", "2026-08-01", "2026-08-02", True, sleep_fn=lambda _: None
    )
    assert attempts == 4
    assert result.get("error")
    assert len(calls) == 4
